/** Características inatas transcritas das páginas de classes da V3 no Notion. */
export interface RPGTrainerClassFeature { name: string; text: string }
export const RPG_TRAINER_CLASS_FEATURES: Readonly<Record<string, readonly RPGTrainerClassFeature[]>> = {
	"arqueologo": [{ "name": "Leitura do Passado", "text": "Após examinar por pelo menos dez minutos uma ruína, artefato, fóssil, inscrição ou local histórico, o Arqueólogo realiza:\n```plain text\nConhecimento: Arqueologia e Fósseis\n```\nou, quando estiver reconstruindo acontecimentos:\n```plain text\nInvestigação\n```\nEm caso de sucesso, além das informações normais, poderá fazer uma pergunta relacionada às evidências disponíveis.\nExemplos:\n- Qual é a idade aproximada?\n- Qual civilização produziu isso?\n- Qual era sua função original?\n- O objeto foi alterado ou danificado?\n- O que provavelmente aconteceu neste local?\n- Existe relação com outro achado conhecido?\n- Há sinais de falsificação?\n- Qual deverá ser a próxima área investigada?\nO Mestre responde de forma verdadeira, mas somente com informações que possam ser deduzidas das evidências existentes.\nSe superar a CD por 10 ou mais, poderá fazer duas perguntas.\nA mesma ruína ou objeto não poderá ser analisado repetidamente para obter novas perguntas, salvo quando novas evidências forem encontradas." }, { "name": "Escavação Cautelosa", "text": "Quando utiliza ferramentas apropriadas para extrair ou preservar um fóssil, artefato ou material histórico e falha no teste por até quatro pontos:\n- O objeto não é destruído.\n- O objeto não é perdido.\n- A extração não é concluída.\n- O trabalho leva mais tempo.\n- Uma nova tentativa exige mudança nas condições, nova abordagem ou ajuda válida.\nSe falhar por cinco ou mais, as consequências normais poderão acontecer.\nEssa característica protege o achado contra pequenos erros, mas não transforma falhas em sucessos automáticos." }],
	"artista": [{ "name": "Cativar a Plateia", "text": "Após realizar uma apresentação solo/grupo com duração mínima de um minuto, o Artista pode fazer um teste de Atuação para influenciar a disposição de uma plateia capaz de vê-lo ou ouvi-lo.\nA CD depende da disposição inicial do público:\n<table header-row=\"true\">\n<tr>\n<td>Disposição</td>\n<td>CD</td>\n</tr>\n<tr>\n<td>Receptiva</td>\n<td>10</td>\n</tr>\n<tr>\n<td>Indiferente</td>\n<td>15</td>\n</tr>\n<tr>\n<td>Desconfiada</td>\n<td>20</td>\n</tr>\n<tr>\n<td>Hostil</td>\n<td>25</td>\n</tr>\n</table>\nEm caso de sucesso, a disposição da plateia melhora em um estágio durante a cena:\n```plain text\nHostil → Desconfiada\nDesconfiada → Indiferente\nIndiferente → Receptiva\n```\nSe superar a CD por 10 ou mais, a disposição melhora em dois estágios.\nEssa mudança não controla a plateia e não obriga ninguém a aceitar pedidos. Ela apenas modifica a forma como o público recebe o Artista e as interações imediatamente relacionadas à apresentação.\nUma plateia envolvida em combate, fugindo de um perigo ou incapaz de prestar atenção não poderá ser afetada.\nO Artista não poderá tentar Cativar a mesma plateia novamente durante a cena." }, { "name": "Expressão Universal", "text": "O Artista consegue transmitir ideias simples por meio de gestos, ritmo, música, dança, expressão corporal ou encenação, mesmo sem compartilhar um idioma com o público.\nEssa característica pode comunicar conceitos como:\n- Perigo.\n- Ajuda.\n- Tristeza.\n- Alegria.\n- Espera.\n- Aproximação.\n- Partida.\n- Silêncio.\n- Confiança.\n- Advertência.\nQuando houver dúvida sobre a clareza da mensagem, o Artista realiza um teste de Atuação.\nExpressão Universal não permite:\n- Traduzir frases completas.\n- Transmitir nomes desconhecidos.\n- Explicar instruções técnicas.\n- Comunicar detalhes exatos.\n- Substituir o conhecimento de um idioma." }, { "name": "Improviso Artístico", "text": "O Artista consegue realizar apresentações mesmo sem possuir os instrumentos, figurinos ou objetos normalmente utilizados por sua arte.\nEle pode adaptar objetos comuns como elementos de apresentação:\n- Recipientes podem funcionar como instrumentos de percussão.\n- Tecidos comuns podem servir como figurino.\n- Objetos cotidianos podem se tornar acessórios de cena.\n- Sons e movimentos corporais podem substituir acompanhamento instrumental.\nA ausência de equipamento artístico apropriado não causa penalidade no teste de Atuação quando existir uma substituição minimamente coerente.\nImproviso Artístico não substitui equipamentos necessários por segurança, alcance, amplificação ou funcionamento técnico. Um objeto improvisado também não adquire valor, qualidade ou propriedades especiais." }],
	"artista-marcial": [{ "name": "Corpo como Arma", "text": "O treinamento do Artista Marcial transforma mãos, pés, cotovelos, joelhos e outras partes do corpo em armas eficazes.\nSeus ataques desarmados causam:\n```plain text\n1d6 + modificador de Força ou Destreza\n```\nO atributo utilizado é escolhido a cada ataque. A escolha representa o estilo aplicado naquele movimento:\n- Força para golpes pesados e diretos.\n- Destreza para golpes rápidos, precisos ou baseados em movimentação.\nO Artista Marcial poderá escolher causar dano letal ou não letal sem sofrer penalidade. Ataques realizados com diferentes partes do corpo seguem a mesma regra; um chute não causa automaticamente mais dano que um soco.\nEnquanto possuir pelo menos uma parte do corpo apropriada livre, ele não será considerado desarmado para efeitos que dependam de portar uma arma.\nA progressão desse dano e técnicas especiais poderão ser adquiridas posteriormente por talentos exclusivos da classe." }, { "name": "Defesa Disciplinada", "text": "Quando não estiver utilizando armadura nem escudo, a Defesa do Artista Marcial será calculada da seguinte forma:\n```plain text\nDefesa = 10 + modificador de Destreza + modificador de Sabedoria\n```\nA Sabedoria representa leitura dos movimentos, controle da distância, postura, respiração e percepção da intenção do adversário.\nEssa Defesa exige que o Artista Marcial:\n- Esteja consciente.\n- Consiga perceber o atacante.\n- Tenha liberdade para se movimentar.\n- Não esteja imobilizado.\nEquipamentos de proteção que não sejam considerados armadura, como roupas reforçadas ou acessórios simples, poderão conceder benefícios somente quando suas regras afirmarem que são compatíveis com Defesa Disciplinada." }, { "name": "Amortecer Impacto", "text": "Quando sofre dano físico, o Artista Marcial poderá usar sua reação para amortecer o impacto.\nO dano recebido será reduzido em:\n```plain text\nBônus de proficiência + modificador de Constituição\n```\nA redução mínima será de 1 ponto.\nAmortecer Impacto representa ações como:\n- Desviar parcialmente um golpe.\n- Proteger uma região vulnerável.\n- Cair acompanhando a força do impacto.\n- Distribuir o peso pelo corpo.\n- Utilizar braços ou pernas para absorver parte do ataque.\nComo utiliza uma reação, poderá ser empregado no máximo uma vez por rodada, mas não possui limite diário de utilizações.\nA característica poderá reduzir dano causado diretamente ao treinador por uma pessoa, objeto, ambiente ou Pokémon. Ela modifica apenas o dano recebido pelo treinador e não altera o poder, a precisão, os atributos ou qualquer cálculo pertencente ao Pokémon atacante.\nAmortecer Impacto não poderá ser utilizado quando o treinador estiver inconsciente, surpreendido pelo ataque ou completamente impedido de reagir." }],
	"atleta": [{ "name": "Mobilidade Atlética", "text": "O deslocamento básico do Atleta será:\n```plain text\n10,5 metros\n```\nIsso corresponde a sete quadrados de 1,5 metro, em vez dos seis quadrados normalmente percorridos por um treinador.\nAlém disso:\n- Levantar-se após cair exige somente 1,5 metro de deslocamento.\n- Uma corrida preparatória para saltar exige apenas 1,5 metro em linha reta.\n- Subir ou descer obstáculos baixos de até metade da sua altura não exige deslocamento adicional.\n- Transpor uma barreira pequena durante uma corrida não interrompe automaticamente o movimento.\nEsses benefícios exigem liberdade de movimento. Terreno realmente difícil, superfícies perigosas ou obstáculos grandes continuam aplicando suas regras normalmente." }, { "name": "Ritmo Sustentado", "text": "O Atleta consegue manter atividades físicas por mais tempo antes de sofrer os efeitos do cansaço.\nQuando uma atividade exigir testes periódicos de Fortitude devido exclusivamente à duração do esforço, o intervalo antes de cada teste será dobrado.\nExemplos:\n- Corridas prolongadas.\n- Natação por longas distâncias.\n- Escaladas extensas.\n- Pedalar durante uma viagem.\n- Remar.\n- Praticar uma modalidade esportiva por várias horas.\n- Perseguir ou fugir de alguém por uma distância prolongada.\nSe normalmente fosse necessário realizar um teste a cada 10 minutos, o Atleta faria o teste a cada 20 minutos.\nRitmo Sustentado não altera testes provocados por:\n- Fome ou sede.\n- Falta de sono.\n- Temperaturas extremas.\n- Doenças ou venenos.\n- Ferimentos.\n- Falta de oxigênio.\n- Sobrecarga acima do limite suportado.\nA característica prolonga o desempenho físico, mas não remove necessidades biológicas nem perigos ambientais." }, { "name": "Fundamentos Esportivos", "text": "O Atleta domina movimentos básicos por meio de repetição, técnica e memória muscular.\nQuando realiza um teste de Atletismo ou Acrobacia dentro de uma atividade esportiva, competição física ou exercício controlado, qualquer resultado natural do d20 entre 1 e 4 será tratado como 5.\nExemplos de aplicação:\n- Corridas.\n- Saltos.\n- Arremessos.\n- Levantamento de peso.\n- Ginástica.\n- Equilíbrio esportivo.\n- Escalada competitiva.\n- Natação.\n- Provas de obstáculos.\n- Esportes coletivos.\n- Disputas de força ou velocidade.\nFundamentos Esportivos não transforma o resultado em sucesso automático. Todos os modificadores são aplicados normalmente, e o total ainda deverá alcançar a CD ou superar o resultado do adversário.\nA característica não se aplica a:\n- Ataques.\n- Iniciativa.\n- Resistências.\n- Manobras de combate.\n- Tentativas de agarrar ou derrubar alguém durante um confronto.\n- Situações nas quais o treinador não consiga controlar minimamente o próprio movimento." }, { "name": "Espírito Competitivo", "text": "Quando participa de uma competição física com regras e objetivo claramente definidos, o Atleta identifica rapidamente o próprio desempenho em relação aos demais participantes.\nApós concluir uma etapa da competição, ele saberá:\n- Se está acima, abaixo ou próximo da média dos competidores.\n- Qual aspecto físico mais prejudicou seu desempenho.\n- Qual participante demonstrou o melhor desempenho naquela etapa.\n- Se seu resultado foi prejudicado por uma falha técnica, falta de força, perda de ritmo ou escolha inadequada de movimento.\nEssa percepção não revela valores numéricos de ficha nem informações que o Atleta não poderia observar. Ela representa experiência competitiva, consciência corporal e capacidade de analisar resultados físicos." }],
	"cientista": [{ "name": "Método Científico", "text": "Quando possui tempo, evidências, meios de análise e ferramentas apropriadas, o Cientista poderá utilizar uma área adequada de Conhecimento para realizar uma análise que normalmente pertenceria a outra perícia.\nEssa característica representa a aplicação de princípios teóricos, exames, cálculos, comparação de dados e procedimentos laboratoriais.\nExemplos:\n- Usar Conhecimento relacionado à Biologia ou Medicina para identificar uma possível doença.\n- Usar Conhecimento relacionado à Pokémon para reconhecer uma alteração fisiológica em um Pokémon.\n- Usar Conhecimento relacionado à Química para identificar uma substância desconhecida.\n- Usar Conhecimento relacionado à Engenharia para descobrir por que uma máquina parou de funcionar.\n- Usar Conhecimento relacionado à Botânica para identificar uma planta e suas propriedades.\n- Usar Conhecimento relacionado à Geologia para analisar uma formação mineral.\n- Usar Conhecimento relacionado à Física para calcular a origem provável de um impacto.\n- Usar Conhecimento relacionado à Computação para interpretar o comportamento de um programa.\nPara utilizar Método Científico, o Cientista deverá possuir:\n- Treinamento na área de Conhecimento apropriada.\n- Evidências ou amostras suficientes.\n- Ferramentas compatíveis com a análise.\n- Tempo para aplicar o procedimento.\nO tempo necessário dependerá da complexidade:\n```plain text\nAnálise simples: aproximadamente 10 minutos\nAnálise detalhada: aproximadamente 1 hora\nPesquisa complexa: definida pelo Mestre\n```\nO teste será realizado com a área de Conhecimento utilizada, no lugar da perícia que normalmente identificaria aquela informação.\nMétodo Científico poderá substituir perícias como:\n- Investigação, para interpretar evidências por meio de uma análise técnica.\n- Medicina, para identificar doenças, lesões ou alterações fisiológicas.\n- Medicina Pokémon, para analisar condições biológicas de um Pokémon.\n- Natureza, para examinar organismos, substâncias ou fenômenos naturais.\n- Ofício, para identificar problemas em processos ou produtos.\n- Tecnologia, para diagnosticar dispositivos, máquinas ou sistemas.\nA substituição será limitada à obtenção e interpretação de informações.\nMétodo Científico não permite:\n- Tratar uma doença ou ferimento.\n- Prestar primeiros socorros.\n- Reparar uma máquina.\n- Operar um dispositivo.\n- Fabricar um objeto.\n- Preparar automaticamente uma substância.\n- Rastrear alguém pelo ambiente.\n- Perceber um perigo sem realizar uma análise.\n- Interagir com um Pokémon.\n- Executar uma atividade prática pertencente à perícia substituída.\nPor exemplo, o Cientista poderá usar Conhecimento para descobrir que uma máquina possui uma falha no sistema de refrigeração, mas ainda precisará de Tecnologia ou do Ofício adequado para repará-la.\nDa mesma forma, poderá identificar uma doença por meio de exames, mas precisará de Medicina para realizar o tratamento." }, { "name": "Registro Reprodutível", "text": "O Cientista poderá transformar uma fórmula científica conhecida em um conjunto de instruções que outra pessoa consiga executar.\nO registro poderá assumir a forma de:\n- Fórmula química.\n- Receita técnica.\n- Diagrama de montagem.\n- Sequência de ativação.\n- Programa simples.\n- Manual ilustrado.\n- Instruções acompanhadas de componentes previamente preparados.\nO Cientista poderá manter somente um Registro Reprodutível ativo por vez. Ao criar um novo, o anterior perde o benefício desta característica e passa a ser apenas uma anotação comum.\nUma pessoa que esteja com o registro poderá produzir o efeito descrito mesmo sem treinamento na área científica correspondente.\nEla não aprende a ciência envolvida. Apenas segue uma sequência preparada para funcionar sob condições determinadas.\nPara executar o procedimento, o usuário ainda precisa possuir um Kit Científico com carga disponível. Cada produção consome a quantidade de cargas indicada pela fórmula; os Registros Reprodutíveis iniciais consomem uma carga por unidade produzida.\nO registro permite que seu portador utilize o Kit Científico apenas para reproduzir aquela fórmula, mesmo sem possuir domínio do kit. Nesse caso:\n- Não recebe o bônus concedido pelo nível do kit.\n- Não poderá utilizar o kit para análises, experimentos ou outras fórmulas.\n- Não poderá alterar, reparar ou adaptar o procedimento.\n- Precisará seguir integralmente as ferramentas, o tempo e as condições descritas.\nO portador poderá utilizar um kit emprestado, mas deverá possuir autorização de seu dono e gastar as cargas desse kit normalmente.\n### Estrutura do registro\nTodo Registro Reprodutível deverá informar:\n```plain text\nFórmula: nome do procedimento\nÁrea científica: Conhecimento utilizado\nComponentes: materiais necessários\nPreparação: tempo necessário\nAtivação: como o efeito é iniciado\nEfeito: resultado produzido\nDuração: quanto tempo permanece\nLimitações: condições em que deixa de funcionar\n```\nO registro poderá incluir componentes parcialmente preparados pelo Cientista. Esses componentes fazem parte do procedimento e deverão acompanhar as instruções.\n### Execução\nPara utilizar o registro, a pessoa deverá:\n- Conseguir compreender as instruções.\n- Possuir o registro durante a preparação.\n- Ter todos os componentes necessários.\n- Possuir as ferramentas indicadas.\n- Respeitar o tempo de preparação.\n- Ser fisicamente capaz de executar as etapas.\nQuando todas as condições forem cumpridas, um procedimento simples produzirá seu efeito sem exigir conhecimento científico nem teste adicional.\nSe o usuário:\n- Substituir componentes;\n- Alterar medidas;\n- Ignorar etapas;\n- Utilizar ferramentas inadequadas;\n- Tentar adaptar a fórmula para outra finalidade;\no funcionamento deixa de ser garantido e poderá exigir um teste apropriado. Uma falha poderá consumir os componentes sem produzir o efeito.\nOs componentes consumíveis são gastos a cada utilização. O registro em si não é consumido.\n### Exemplo: Fórmula de Luminescência\n```plain text\nFórmula: Luminescência Química\nÁrea científica: Conhecimento — Química\nComponentes: solução reagente, recipiente apropriado e material absorvente\nPreparação: 1 minuto\nAtivação: misturar ou romper o recipiente interno\nDuração: 1 hora\n```\nO usuário prepara uma pequena fonte de luz química.\nEla ilumina claramente uma área de aproximadamente 6 metros e produz iluminação fraca por mais 6 metros.\nO material poderá ser:\n- Colocado dentro de um recipiente.\n- Preso em uma superfície.\n- Aplicado a um objeto apropriado.\n- Carregado como uma fonte de luz.\n- Utilizado para marcar um caminho.\nO efeito não produz calor relevante, não incendeia objetos e não causa dano. Água, produtos incompatíveis ou destruição do recipiente poderão encerrar o efeito.\nEssa fórmula ocupa o mesmo espaço mecânico que uma magia simples de luz, mas sua existência é explicada por uma reação química.\n### Outros efeitos possíveis\nRegistros científicos básicos poderão produzir efeitos equivalentes a utilidades simples, como:\n- Criar luz química.\n- Produzir fumaça colorida de sinalização.\n- Aquecer uma pequena quantidade de água.\n- Resfriar temporariamente um recipiente.\n- Criar uma cola de secagem rápida.\n- Produzir um odor forte para marcar um local.\n- Revelar a presença de determinada substância.\n- Criar tinta visível apenas sob uma luz específica.\n- Produzir um som de alarme simples.\n- Purificar uma pequena quantidade de água.\n- Preservar temporariamente uma amostra orgânica.\n- Criar uma espuma capaz de vedar uma pequena abertura.\n- Produzir um material que muda de cor conforme temperatura ou acidez.\nCada efeito deverá possuir componentes, alcance, duração e limitações próprios.\n### Criação de uma fórmula\nPara colocar uma fórmula no Registro Reprodutível, o Cientista deverá:\n1. Conhecer a fórmula ou desenvolvê-la durante a campanha.\n2. Possuir treinamento na área de Conhecimento correspondente.\n3. Ter acesso aos componentes e ferramentas necessários.\n4. Produzir o efeito com sucesso ao menos uma vez.\n5. Preparar instruções adequadas para outra pessoa.\nFórmulas descobertas durante a campanha poderão continuar conhecidas pelo Cientista. Entretanto, somente uma delas poderá estar preparada como Registro Reprodutível para ser utilizada por outra pessoa.\n### Limites científicos\nO registro não poderá produzir um efeito sem uma explicação compatível com o mundo.\nEle não poderá:\n- Criar matéria do nada.\n- Produzir energia ilimitada.\n- Curar instantaneamente ferimentos graves.\n- Ressuscitar alguém.\n- Teletransportar pessoas ou objetos.\n- Controlar mentes.\n- Alterar permanentemente um organismo em poucos segundos.\n- Conceder capacidades psíquicas.\n- Reproduzir poderes exclusivos de Pokémon sem uma tecnologia já existente que explique isso.\n- Aumentar atributos, dano, precisão ou resistência de Pokémon em combate.\nEfeitos mais complexos poderão exigir talentos exclusivos, equipamentos avançados, instalações apropriadas ou fórmulas descobertas durante a campanha. Assim, a característica começa oferecendo uma espécie de “magia científica” utilitária e limitada, enquanto fórmulas mais poderosas poderão fazer parte da progressão do Cientista.\n<page url=\"https://app.notion.com/p/3e1508f8aa6c808cb447fd3347bae633\">Registros iniciais</page>" }],
	"cozinheiro": [{ "name": "Cozinha de Campo", "text": "O Cozinheiro consegue preparar refeições adequadas mesmo sem possuir uma cozinha completa.\nDesde que tenha uma fonte de calor segura, um recipiente apropriado e utensílios minimamente adaptáveis, a ausência de uma cozinha não causa penalidade em testes de Ofício — Culinária.\nO Cozinheiro poderá improvisar recursos como:\n- Pedras limpas como superfície de preparo.\n- Folhas apropriadas como proteção ou embalagem.\n- Gravetos seguros como espetos.\n- Recipientes metálicos como panelas.\n- Tecidos limpos como filtros.\n- Braseiros ou fogueiras como fontes de calor.\n- Neve, água corrente ou solo fresco para resfriamento.\n- Caixas e bolsas como câmaras improvisadas de conservação.\nA qualidade da refeição continua dependendo dos ingredientes e do teste realizado.\nCozinha de Campo não substitui equipamentos indispensáveis para técnicas complexas. Processos que exigem pressão controlada, temperatura exata, esterilização, fermentação prolongada ou instrumentos especializados continuam exigindo os recursos correspondentes." }, { "name": "Aproveitamento Integral", "text": "O Cozinheiro sabe utilizar partes normalmente desperdiçadas dos ingredientes, reorganizar porções e evitar perdas durante o preparo.\nAo produzir pelo menos quatro porções de uma mesma refeição, ele poderá criar uma porção adicional sem aumentar a quantidade de ingredientes utilizada.\nExemplos:\n```plain text\n4 porções preparadas → 5 porções\n8 porções preparadas → 10 porções\n12 porções preparadas → 15 porções\n```\nAs porções adicionais possuem a mesma qualidade e os mesmos efeitos das originais.\nEsse benefício representa:\n- Aproveitamento de talos, cascas e sementes comestíveis.\n- Controle adequado das quantidades.\n- Redução de perdas durante cortes.\n- Reutilização culinária segura de caldos e aparas.\n- Organização eficiente dos ingredientes.\nA característica não funciona quando cada porção exige um componente individual e indivisível.\nPor exemplo, quatro frutas inteiras não poderão produzir cinco frutas. Entretanto, poderão render cinco porções de uma receita preparada com elas, caso existam outros ingredientes suficientes." }, { "name": "Refeição Revigorante", "text": "Ao preparar uma refeição completa durante um período de descanso, o Cozinheiro poderá torná-la especialmente restauradora para os treinadores que a consumirem.\nA preparação exige:\n- Ingredientes apropriados para uma refeição completa.\n- Pelo menos 30 minutos de preparo.\n- Um teste de Ofício — Culinária.\n- Tempo suficiente para que os beneficiados comam sem interrupção.\nA CD depende das condições de preparo:\n<table header-row=\"true\">\n<tr>\n<td>Condição</td>\n<td>CD</td>\n</tr>\n<tr>\n<td>Cozinha equipada e ingredientes adequados</td>\n<td>10</td>\n</tr>\n<tr>\n<td>Cozinha improvisada ou ingredientes limitados</td>\n<td>15</td>\n</tr>\n<tr>\n<td>Ambiente desfavorável ou recursos precários</td>\n<td>20</td>\n</tr>\n</table>\nEm caso de sucesso, cada treinador que consumir uma porção durante o descanso recuperará Pontos de Vida adicionais iguais a:\n```plain text\nBônus de proficiência do Cozinheiro + modificador de Sabedoria do Cozinheiro\n```\nA recuperação mínima será de 1 PV.\nUma mesma pessoa recebe esse benefício somente uma vez por período de descanso, independentemente de quantas porções consumir. Refeições Revigorantes diferentes não acumulam seus efeitos no mesmo descanso.\nPokémon poderão consumir refeições apropriadas preparadas dessa forma, mas não recebem a recuperação adicional de PV. A comida poderá atender às necessidades alimentares deles, mas não altera dano, atributos, condições, PP ou qualquer cálculo de combate." }],
	"coreografo": [{ "name": "Linguagem Coreográfica", "text": "Após ensaiar por pelo menos dez minutos com um Pokémon disposto a cooperar e que possua pelo menos 50 pontos de amizade, o Coreógrafo desenvolve sinais discretos por meio de gestos, sons, palavras curtas ou ritmo.\nSe a amizade do Pokémon cair abaixo de 50, ele deixa de responder de maneira confiável à Linguagem Coreográfica até recuperar esse valor.\nEsses sinais permitem transmitir comandos simples de movimentação e apresentação, como avançar, recuar, parar, saltar, trocar de posição ou iniciar uma parte ensaiada, sem que o público necessariamente os perceba.\nA característica não transmite pensamentos ou instruções complexas e não concede benefícios em batalhas Pokémon." }, { "name": "Ensaio Conjunto", "text": "Após ensaiar por pelo menos uma hora com um Pokémon disposto a cooperar, o Coreógrafo passa a receber os seguintes benefícios sempre que atuar com ele:\n- `+2` nos testes de Atuação do treinador quando com o pokemon.\n- Sua nota de Sincronia no concurso não poderá ser inferior a `3`.\nO Coreógrafo poderá manter uma sequência ensaiada diferente com cada Pokémon. Alterações significativas na apresentação exigem um novo ensaio.\nEsses benefícios representam a preparação e a coordenação entre ambos. Eles não alteram golpes, PP, atributos, precisão, poder nem ações do Pokémon." }, { "name": "Presença Compartilhada", "text": "Quando o Coreógrafo e um Pokémon participam juntos de uma apresentação, ele consegue dividir a atenção do público de maneira intencional.\nAntes de realizar um teste de Atuação, o Coreógrafo declara quem deverá ocupar o foco principal daquele momento:\n```plain text\nO treinador\nO Pokémon\nA interação entre ambos\n```\nEm caso de sucesso no teste, o público compreende corretamente onde está o centro da apresentação.\nIsso permite:\n- Preparar a entrada do Pokémon.\n- Desviar a atenção enquanto o Pokémon muda de posição.\n- Criar expectativa antes de um movimento.\n- Evitar que o treinador esconda involuntariamente a ação do Pokémon.\n- Fazer uma transição clara entre duas partes da apresentação.\n- Destacar a relação entre treinador e Pokémon.\nPresença Compartilhada não aumenta diretamente a pontuação da apresentação. Seu benefício é narrativo e posicional, permitindo que a intenção da coreografia seja compreendida sem ambiguidades quando o teste for bem-sucedido." }],
	"criador-pokemon": [{ "name": "Afinidade Natural", "text": "O Criador Pokémon transmite segurança e entende como se aproximar de Pokémon selvagens sem parecer uma ameaça.\nA disposição inicial de um Pokémon selvagem em relação ao Criador será considerada um grau melhor, desde que ele ainda não tenha entrado em confronto com o Criador ou seu grupo.\n```plain text\nHostil → Desconfiado\nDesconfiado → Indiferente\nIndiferente → Receptivo\n```\nO benefício deixa de ser aplicado se o Criador ou seus companheiros:\n- Atacarem o Pokémon.\n- Tentarem capturá-lo à força.\n- Invadirem deliberadamente seu território.\n- Ameaçarem seus filhotes ou grupo.\n- Realizarem outra ação que o faça considerar o grupo uma ameaça.\nA característica não controla o Pokémon e não remove motivações importantes. Um Pokémon protegendo seus filhotes, sob influência externa ou determinado a atacar poderá continuar hostil.\nAlém disso, todo Pokémon capturado pelo Criador começa com:\n```plain text\n+10 de Amizade\n```\nEsse aumento é aplicado depois da captura e respeita o valor máximo de Amizade. Ele não melhora a chance de captura nem interfere no combate anterior." }, { "name": "Reprodução Acompanhada", "text": "Ao examinar um ovo por pelo menos dez minutos e possuir condições seguras para manuseá-lo, o Criador Pokémon identifica:\n- Quanto tempo falta para o ovo chocar.\n- Qual espécie nascerá.\n- Qual forma nascerá, quando já estiver definida.\n- O sexo do Pokémon, quando aplicável e já definido.\n- Se o desenvolvimento está ocorrendo normalmente.\n- Se existem sinais de complicação.\n- Quais condições ambientais o ovo precisa.\n- Quais cuidados serão necessários imediatamente após o nascimento.\nO tempo restante será informado utilizando a medida empregada pela campanha, como horas ou dias dentro do RPG.\nReprodução Acompanhada não revela:\n- IVs.\n- EVs.\n- Se o Pokémon será shiny.\n- Habilidade.\n- Golpes.\n- Outros valores ocultos que não possam ser identificados pela análise do ovo.\nA característica fornece informações e permite acompanhar o desenvolvimento, mas não acelera o nascimento nem modifica o Pokémon que nascerá." }, { "name": "Primeiros Cuidados", "text": "Fora de combate, o Criador Pokémon poderá recuperar um Pokémon desmaiado para:\n```plain text\n1 PV\n```\nO procedimento exige:\n- Um Kit de Primeiros Socorros Pokémon.\n- Uma carga utilizável do kit.\n- Dez minutos de atendimento sem interrupção.\n- Um local onde o Pokémon possa permanecer em segurança.\nO atendimento não remove condições, não restaura PP e não recupera PV além do primeiro ponto. Depois disso, o Pokémon ainda precisará de tratamento, descanso ou atendimento em um Centro Pokémon.\nDepois de receber Primeiros Cuidados, o mesmo Pokémon não poderá se beneficiar novamente dessa característica durante os próximos:\n```plain text\n7 dias dentro do RPG\n```\nEsse intervalo acompanha o Pokémon, independentemente de qual Criador tente atendê-lo. Assim, vários Criadores não poderão utilizar a característica repetidamente sobre o mesmo Pokémon.\nA carga do kit será consumida mesmo que o Pokémon ainda precise de tratamento adicional. Primeiros Cuidados não consome nem substitui o item Revive e não poderá ser utilizado durante uma batalha." }],
	"detetive": [{ "name": "Preservação da Cena", "text": "O Detetive poderá delimitar uma área de investigação e orientar seus aliados sobre como se movimentar, procurar pistas e manipular evidências dentro dela.\nQuando o Detetive ou um aliado orientado falhar por até quatro pontos em um teste realizado dentro da área:\n- Evidências não são destruídas.\n- Objetos não são danificados.\n- Rastros não são apagados.\n- A cena não é contaminada pela tentativa.\n- A ação pretendida não é concluída.\nUma nova tentativa exige outra abordagem, mais tempo, ferramentas diferentes ou alguma mudança nas condições.\nFalhas por cinco ou mais são consideradas graves e poderão comprometer a cena normalmente. A característica também não protege contra ações deliberadas, interferência externa, clima ou passagem do tempo." }, { "name": "Depoimento Cruzado", "text": "Ao interagir com outras pessoas, o Detetive poderá utilizar Investigação no lugar de Intuição.\nIsso permite analisar declarações, comparar informações, perceber contradições e avaliar se o comportamento de alguém é coerente com os fatos conhecidos.\nNesse caso, o teste utiliza Inteligência e o treinamento em Investigação, em vez de Sabedoria e Intuição.\nDepoimento Cruzado não revela pensamentos nem obriga alguém a responder ou dizer a verdade. Ele permite apenas interpretar a pessoa por meio de lógica, evidências e consistência das informações." }, { "name": "Reconstrução dos Fatos", "text": "Após examinar uma cena por pelo menos dez minutos, o Detetive poderá realizar um teste de Investigação para reconstruir os acontecimentos a partir das evidências disponíveis.\nEm caso de sucesso, poderá fazer uma pergunta:\n- Qual foi a provável sequência dos acontecimentos?\n- Por onde alguém entrou ou saiu?\n- Quantas pessoas ou criaturas parecem ter participado?\n- Qual ação provavelmente ocorreu primeiro?\n- Algum elemento da cena parece ter sido encenado?\n- Existe sinal de que algo foi removido?\n- Qual evidência contradiz a explicação aparente?\n- Para onde os rastros ou acontecimentos provavelmente continuaram?\n- Qual deverá ser a próxima evidência procurada?\nSe superar a CD por 10 ou mais, poderá fazer duas perguntas.\nO Mestre responde de forma verdadeira, mas somente com conclusões sustentadas pelas evidências encontradas.\nA mesma cena não poderá ser analisada repetidamente para obter novas perguntas, salvo quando uma nova pista for descoberta ou as condições da investigação mudarem." }],
	"diplomata": [{ "name": "Etiqueta e Protocolo", "text": "Após observar uma reunião, instituição ou comunidade por pelo menos dez minutos, ou receber orientações de alguém pertencente a ela, o Diplomata reconhece:\n- Quem possui autoridade formal.\n- Quem exerce influência sem ocupar o cargo principal.\n- A forma apropriada de tratamento.\n- A ordem esperada das apresentações.\n- Assuntos considerados inadequados naquele contexto.\n- Costumes públicos importantes.\n- Quem possui autoridade para negociar ou firmar um acordo.\nInformações públicas e comportamentos evidentes são reconhecidos sem teste. Regras ocultas, tradições desconhecidas ou relações secretas poderão exigir Conhecimento ou Investigação.\nEssa característica evita erros básicos de etiqueta, mas não garante que as pessoas recebam o Diplomata de maneira favorável." }, { "name": "Voz de Trégua", "text": "Quando um conflito social estiver prestes a se transformar em violência, o Diplomata poderá pedir uma interrupção e apresentar uma proposta imediata de diálogo.\nEle realiza um teste de Persuasão contra uma CD definida pela disposição do grupo mais resistente:\n<table header-row=\"true\">\n<tr>\n<td>Disposição</td>\n<td>CD</td>\n</tr>\n<tr>\n<td>Indiferente</td>\n<td>10</td>\n</tr>\n<tr>\n<td>Desconfiada</td>\n<td>15</td>\n</tr>\n<tr>\n<td>Hostil</td>\n<td>20</td>\n</tr>\n<tr>\n<td>Determinada a atacar</td>\n<td>25</td>\n</tr>\n</table>\nEm caso de sucesso, as partes interrompem a escalada por tempo suficiente para ouvir uma proposta breve.\nDurante esse intervalo:\n- Ninguém é obrigado a abandonar suas exigências.\n- As partes poderão recusar a proposta.\n- A negociação poderá fracassar.\n- Qualquer ameaça ou agressão encerra imediatamente a trégua.\nVoz de Trégua não funciona quando o combate já começou, quando uma das partes é incapaz de compreender o Diplomata ou quando existe uma ameaça imediata que não permite conversa." }, { "name": "Mediação Estruturada", "text": "Quando duas ou mais partes aceitam participar de uma negociação, o Diplomata poderá organizar a conversa para encontrar um acordo possível.\nDepois de ouvir cada lado por pelo menos dez minutos, ele identifica:\n- Uma exigência indispensável de cada parte.\n- Uma concessão que cada parte parece disposta a considerar.\n- O principal obstáculo aparente para o acordo.\n- Quem realmente possui autoridade para aceitar os termos.\nEssas informações consideram o que foi demonstrado durante a negociação. Mentiras, interesses secretos ou exigências deliberadamente escondidas ainda poderão exigir Intuição ou Investigação.\nAo apresentar uma proposta que respeite as exigências indispensáveis identificadas, o Diplomata recebe:\n```plain text\n+2 no teste de Persuasão para concluir aquele acordo\n```\nO bônus não se aplica se a proposta ignorar uma das partes, ocultar consequências importantes ou exigir algo que ela já declarou inaceitável." }],
	"encantador": [{ "name": "Primeira Impressão", "text": "Quando conhece uma pessoa que ainda não possui opinião formada sobre ele, o Encantador é inicialmente tratado como se sua disposição estivesse um grau melhor:\n```plain text\nDesconfiada → Indiferente\nIndiferente → Receptiva\n```\nEsse benefício permanece durante a primeira interação social entre ambos.\nPrimeira Impressão não funciona quando a pessoa:\n- Já conhece a reputação do Encantador.\n- Foi alertada especificamente contra ele.\n- Possui um motivo pessoal para desconfiar dele.\n- Acabou de presenciar uma ação negativa praticada por ele.\n- Já iniciou a interação de maneira hostil.\nA característica não cria atração, amizade ou confiança permanente. As ações do Encantador durante a conversa determinarão qual será a disposição da pessoa depois da primeira interação." }, { "name": "Leitura Afetiva", "text": "Depois de conversar com uma pessoa por pelo menos um minuto, o Encantador reconhece seu estado emocional em relação à interação.\nSem necessidade de teste, ele identifica:\n- Se a pessoa está confortável ou desconfortável.\n- Se deseja continuar ou encerrar a conversa.\n- Se está receptiva ou resistente à aproximação.\n- Se determinado assunto despertou interesse.\n- Se uma abordagem provocou irritação, vergonha ou insegurança.\n- Se uma aproximação afetiva ou romântica é bem recebida, indesejada ou inconclusiva.\nA característica não revela pensamentos, segredos ou a causa exata de uma emoção. Uma pessoa treinada em Enganação ainda poderá tentar esconder suas reações, exigindo um teste de Intuição.\nLeitura Afetiva permite reconhecer limites e reações; não permite ignorá-los ou controlar os sentimentos de outra pessoa." }, { "name": "Centro das Atenções", "text": "O Encantador poderá direcionar deliberadamente a atenção das pessoas presentes para si por meio de conversa, comportamento, charme ou apresentação.\nEle realiza um teste de Persuasão ou Atuação. Quem tiver motivo para resistir poderá realizar um teste oposto de Intuição.\nEm caso de sucesso, enquanto o Encantador continuar sustentando a interação:\n- A atenção social permanece concentrada nele.\n- Aliados recebem vantagem para realizar ações discretas que não sejam diretamente observadas.\n- Mudanças pequenas no ambiente chamam menos atenção.\n- Uma pessoa poderá sair silenciosamente da conversa ou do grupo.\n- Um aliado poderá esconder ou recuperar discretamente um objeto pequeno.\nCentro das Atenções não permite ocultar:\n- Uma agressão.\n- Uma ameaça evidente.\n- Um objeto grande sendo transportado.\n- Uma ação realizada diretamente diante do observador.\n- Algo que represente perigo imediato.\n- Uma ação que o Encantador também precise realizar.\nA característica termina quando o Encantador deixa de sustentar a interação, quando ocorre uma ameaça evidente ou quando alguém percebe uma ação que não poderia ser escondida apenas por distração." }],
	"explorador": [{ "name": "Desbravador", "text": "Durante viagens e explorações fora de combate, terrenos naturais difíceis não reduzem o deslocamento do Explorador.\nIsso inclui:\n- Vegetação densa.\n- Lama moderada.\n- Neve baixa.\n- Pedras irregulares.\n- Encostas comuns.\n- Rios rasos.\n- Trilhas parcialmente destruídas.\nQuando lidera um grupo e possui pelo menos dez minutos para analisar o trajeto, o Explorador também poderá escolher uma passagem mais segura. Os aliados que seguirem suas orientações atravessam aquele trecho sem a penalidade normal de terreno difícil.\nDesbravador não remove perigos nem permite atravessar locais fisicamente impossíveis. Paredões, precipícios, correntezas fortes, neve profunda e terrenos extraordinários continuam exigindo testes, equipamentos ou rotas alternativas." }, { "name": "Rastreador Persistente", "text": "O Explorador recebe:\n```plain text\n+2 nos testes de Sobrevivência relacionados a rastreamento\n```\nO bônus se aplica para:\n- Encontrar rastros.\n- Seguir uma trilha.\n- Determinar a direção tomada.\n- Estimar há quanto tempo alguém passou.\n- Identificar sinais de passagem.\n- Retomar um rastro perdido.\n- Distinguir rastros sobrepostos.\n- Perseguir alguém por ambientes naturais.\nO benefício não se aplica a outras utilizações de Sobrevivência, como orientação, obtenção de alimento, preparação de abrigo ou previsão do clima." }, { "name": "Acampamento Seguro", "text": "Com pelo menos trinta minutos de trabalho, o Explorador poderá organizar um acampamento adequado para o grupo.\nEle escolhe um local que ofereça, quando disponível:\n- Proteção contra vento e chuva.\n- Distância segura de áreas de deslizamento ou inundação.\n- Espaço para treinadores e Pokémon descansarem.\n- Posição apropriada para vigília.\n- Local seguro para armazenar alimentos.\n- Área adequada para uma fogueira.\n- Rotas de entrada e saída.\n- Menor exposição a Pokémon selvagens territoriais.\nDurante o descanso, integrantes do acampamento recebem vantagem em testes de Fortitude contra condições climáticas comuns, desde que permaneçam dentro da área preparada.\nAlém disso, o grupo não deixa rastros ou resíduos evidentes depois de desmontar o acampamento, desde que siga as instruções do Explorador e dedique dez minutos à limpeza.\nAcampamento Seguro não impede ataques, não torna o grupo invisível e não protege contra condições extremas sem equipamento apropriado." }, { "name": "Cartografia de Campo", "text": "Enquanto viaja, o Explorador poderá registrar o caminho percorrido por meio de mapas, anotações, marcos e referências naturais.\nUm mapa produzido dessa forma indica:\n- Direção geral.\n- Distâncias aproximadas.\n- Bifurcações.\n- Fontes de água encontradas.\n- Obstáculos importantes.\n- Locais adequados para descanso.\n- Áreas perigosas identificadas.\n- Pontos de referência visíveis.\nO Explorador consegue refazer uma rota que tenha registrado sem realizar novos testes de orientação, desde que o terreno não tenha sofrido mudanças significativas.\nOutra pessoa que consiga interpretar o mapa recebe vantagem nos testes de Sobrevivência para seguir exatamente aquela rota.\nO mapa não revela áreas que o Explorador não visitou e poderá se tornar impreciso caso estradas, rios, construções ou características do terreno sejam alterados." }],
	"fotografo": [{ "name": "Olhar pela Lente", "text": "Enquanto utiliza um equipamento fotográfico apropriado, o Fotógrafo recebe:\n```plain text\n+2 em testes de Percepção visual realizados através da câmera\n```\nO bônus poderá ser utilizado para:\n- Observar algo distante.\n- Encontrar detalhes em uma cena.\n- Acompanhar o movimento de um alvo.\n- Escolher o melhor momento para uma fotografia.\n- Identificar algo parcialmente escondido.\n- Examinar uma área utilizando ampliação.\n- Procurar diferenças visuais entre objetos ou indivíduos.\nO bônus não se aplica a audição, olfato, tato ou percepções que não possam ser auxiliadas pela câmera.\nA qualidade e o alcance do equipamento ainda limitam aquilo que poderá ser observado." }, { "name": "Registro Oportuno", "text": "Quando percebe um acontecimento visual repentino, o Fotógrafo poderá usar sua reação para tentar registrá-lo antes que desapareça.\nIsso poderá ser utilizado para fotografar:\n- Uma pessoa deixando o local.\n- Um Pokémon que apareceu brevemente.\n- Um objeto sendo entregue.\n- Uma expressão ou gesto importante.\n- Um fenômeno rápido.\n- Uma placa ou veículo em movimento.\n- O instante em que algo foi quebrado ou alterado.\nSe houver dúvida sobre a qualidade do registro, o Fotógrafo realiza um teste de Ofício — Fotografia.\nA imagem registra somente aquilo que estava dentro do enquadramento e que o equipamento era capaz de captar.\nRegistro Oportuno não interrompe ações, não concede prioridade e não interfere em ataques ou movimentos de Pokémon. Ele permite somente produzir um registro visual do acontecimento." }, { "name": "Aproximação Cuidadosa", "text": "Quando se aproxima de uma pessoa ou Pokémon exclusivamente para observar ou fotografar, o Fotógrafo poderá utilizar Ofício — Fotografia no lugar de Furtividade.\nA aproximação deverá ser lenta e não poderá incluir:\n- Ataques.\n- Tentativas de captura.\n- Ameaças.\n- Movimentos bruscos.\n- Invasão deliberada de um abrigo ou ninho.\n- Qualquer ação que represente perigo imediato.\nEm caso de sucesso, o Fotógrafo alcança uma posição adequada sem chamar atenção ou provocar uma reação defensiva.\nDepois de realizar uma ação diferente de observar ou fotografar, as próximas tentativas utilizam Furtividade normalmente." }, { "name": "Documentação Visual", "text": "Quando possui tempo para fotografar uma cena, o Fotógrafo consegue produzir um conjunto de imagens organizado para análise posterior.\nO registro poderá documentar:\n- Posição dos objetos.\n- Estado do ambiente.\n- Marcas visíveis.\n- Pessoas presentes.\n- Pokémon encontrados.\n- Danos e alterações.\n- Textos ou símbolos visíveis.\n- Pontos de entrada e saída.\n- Sequência aparente de um acontecimento.\nUma pessoa que examine essas imagens poderá realizar testes de Investigação ou Percepção visual como se estivesse observando a cena no momento em que ela foi fotografada.\nA análise ficará limitada ao que aparece nas imagens. Ela não permite:\n- Observar áreas fora do enquadramento.\n- Recuperar detalhes que a câmera não registrou.\n- Ouvir sons.\n- Identificar cheiros.\n- Examinar o interior de objetos fechados.\n- Perceber mudanças ocorridas depois das fotografias.\nQuando o Fotógrafo produz uma documentação completa, uma falha posterior na análise não destrói nem altera o registro. Outra pessoa poderá examiná-lo utilizando uma abordagem diferente ou procurando outra informação." }],
	"guarda-pokemon": [{ "name": "Treinamento Tático", "text": "O Guarda Pokémon possui treinamento com armas a distância e equipamentos de contenção utilizados por forças de segurança.\nEle será considerado treinado com:\n- Armas de distância simples.\n- Armas de contenção.\n- Algemas e imobilizadores.\n- Escudos de segurança.\n- Equipamentos de patrulha.\n- Instrumentos não letais autorizados.\nAs armas e categorias exatas serão determinadas quando os equipamentos do sistema forem definidos.\nO Guarda poderá sacar ou guardar uma arma de distância ou equipamento de contenção como parte da ação utilizada para manuseá-lo.\nEsse treinamento pertence ao Guarda. Ele não concede qualquer benefício aos ataques ou ações de seus Pokémon." }, { "name": "Mira de Contenção", "text": "Quando utiliza uma arma de distância contra uma pessoa, o Guarda poderá gastar uma ação mirando cuidadosamente.\nSe não se deslocar depois de começar a mirar, receberá:\n```plain text\n+2 no próximo ataque à distância\n```\nO ataque deverá ser realizado até o final de seu próximo turno. Mover-se, perder a visão do alvo ou sofrer uma condição que impeça a concentração encerra a mira.\nAntes de realizar o ataque, o Guarda poderá declarar que pretende conter o alvo. Se o ataque reduzir uma pessoa a 0 PV, ele poderá deixá-la inconsciente e estável em vez de causar um ferimento letal.\nMira de Contenção também poderá ser utilizada contra objetos, mecanismos ou partes do ambiente, mas não concede o benefício não letal nesses casos.\nA característica não poderá ser utilizada para atacar um Pokémon participante de uma batalha nem interferir em um confronto entre Pokémon." }, { "name": "Contenção Treinada", "text": "O Guarda recebe:\n```plain text\n+2 em testes de Atletismo para agarrar, imobilizar ou conduzir uma pessoa\n```\nO bônus também se aplica para:\n- Manter uma pessoa imobilizada.\n- Impedir que ela alcance um objeto.\n- Retirar uma arma de suas mãos por meio de força física.\n- Colocar algemas ou outro imobilizador em alguém contido.\n- Conduzir uma pessoa que já esteja imobilizada.\nContenção Treinada não permite agarrar automaticamente alguém nem concede autoridade legal sobre a pessoa.\nA característica é destinada à contenção humana. Ela não se aplica contra Pokémon nem altera manobras realizadas em batalhas Pokémon." }],
	"ladino": [{ "name": "Manipulação Cuidadosa", "text": "Quando utiliza Ladinagem para abrir uma fechadura, desarmar uma armadilha ou manipular um mecanismo de segurança e falha por até quatro pontos:\n- A fechadura não é danificada.\n- A ferramenta não fica presa.\n- A armadilha não é ativada.\n- O mecanismo não é bloqueado permanentemente.\n- A tentativa não deixa sinais evidentes de adulteração.\n- A ação pretendida não é concluída.\nUma nova tentativa exige mais tempo, outra ferramenta, uma abordagem diferente ou mudança nas condições.\nFalhas por cinco ou mais produzem as consequências normais.\nManipulação Cuidadosa não protege contra dispositivos que sejam ativados simplesmente pelo contato ou que o Ladino não tenha identificado antes de manipular." }, { "name": "Passagem Discreta", "text": "Durante infiltrações e deslocamentos fora de combate, o Ladino poderá se mover furtivamente em seu deslocamento normal sem sofrer penalidade por velocidade.\nEle ainda precisará realizar testes de Furtividade quando houver possibilidade de ser percebido.\nA característica não permite:\n- Correr furtivamente sem penalidade.\n- Atravessar uma área diretamente observada.\n- Permanecer escondido sem cobertura.\n- Ignorar barulho produzido por equipamentos.\n- Esconder outras pessoas automaticamente.\n- Realizar ações evidentes sem revelar sua posição.\nPassagem Discreta permite avançar com eficiência, mas não substitui as condições necessárias para permanecer oculto." }, { "name": "Mãos Leves", "text": "Quando utiliza Ladinagem para manipular discretamente um objeto pequeno e falha por até quatro pontos:\n- A ação não é concluída.\n- O objeto permanece onde estava.\n- A pessoa envolvida não percebe automaticamente a tentativa.\n- O Ladino não deixa sinais evidentes do que tentou fazer.\nA característica poderá ser utilizada para:\n- Retirar um objeto de um bolso ou bolsa acessível.\n- Colocar discretamente um objeto com alguém.\n- Esconder algo pequeno em suas roupas.\n- Trocar dois objetos semelhantes.\n- Recuperar um objeto sem chamar atenção.\n- Passar algo discretamente para um aliado.\n- Manipular um objeto pequeno enquanto está sendo observado.\nUma nova tentativa exige outra oportunidade ou mudança na abordagem. Falhas por cinco ou mais produzem as consequências normais e poderão fazer o Ladino ser percebido." }],
	"medico": [{ "name": "Atendimento Emergencial", "text": "Fora de combate, o Médico poderá utilizar um Kit de Primeiros Socorros e dez minutos de atendimento para recuperar um paciente desmaiado para:\n```plain text\n1 PV\n```\nO procedimento exige:\n- Uma carga utilizável do kit.\n- Um local minimamente seguro.\n- Dez minutos sem interrupção.\n- Acesso físico ao paciente.\nDepois de receber Atendimento Emergencial, o paciente não poderá se beneficiar novamente dessa característica até completar um descanso longo ou receber tratamento adequado em uma instalação médica.\nO procedimento:\n- Não remove condições.\n- Não restaura PV adicionais.\n- Não substitui uma cirurgia.\n- Não cura doenças ou venenos.\n- Não poderá ser realizado durante um confronto.\nQuando utilizado em uma pessoa, exige Medicina. Quando utilizado em um Pokémon, exige treinamento em Medicina Pokémon.\nO atendimento não altera atributos, PP ou qualquer característica de combate do Pokémon." }, { "name": "Recuperação Assistida", "text": "Durante um período de descanso, o Médico poderá acompanhar a recuperação de uma quantidade de pacientes igual a:\n```plain text\n1 + modificador de Sabedoria do Médico\n```\nO mínimo será de um paciente.\nO atendimento exige materiais médicos apropriados e pelo menos trinta minutos dedicados a cada paciente durante o descanso.\nAo final, cada paciente recupera PV adicionais iguais a:\n```plain text\nBônus de proficiência do Médico + modificador de Sabedoria do Médico\n```\nA recuperação mínima será de 1 PV.\nUma mesma criatura recebe o benefício somente uma vez no mesmo período de descanso. Acompanhamentos realizados por vários Médicos não acumulam seus efeitos.\nPara atender uma pessoa, o Médico utiliza Medicina. Para atender um Pokémon, deverá possuir treinamento em Medicina Pokémon.\nA recuperação ocorre fora de combate e não modifica atributos, golpes, PP ou outras características competitivas do Pokémon." }, { "name": "Rotina de Plantão", "text": "O Médico está acostumado a jornadas prolongadas, interrupções constantes e períodos reduzidos de recuperação.\nEle precisa de apenas metade do tempo normal para concluir um descanso:\n```plain text\nDescanso curto de 1 hora → 30 minutos\nDescanso longo de 8 horas → 4 horas\n```\nAo completar esse período reduzido, recebe normalmente todos os benefícios correspondentes ao descanso realizado.\nO Médico ainda poderá obter os benefícios de apenas um descanso longo dentro do mesmo intervalo em que outra pessoa poderia realizar um. A característica reduz o tempo necessário, mas não permite acumular vários descansos longos consecutivos.\nInterromper o descanso com atividades extenuantes, confrontos ou procedimentos médicos prolongados impede sua conclusão normalmente." }],
	"mentalista": [{ "name": "Leitura Fria", "text": "Depois de observar uma pessoa por pelo menos um minuto, o Mentalista consegue formar uma análise inicial a partir de postura, vestimentas, fala, gestos e reações.\nEle poderá identificar uma das seguintes informações:\n- O estado emocional predominante.\n- Se a pessoa está confortável naquele ambiente.\n- Se está acostumada a exercer autoridade.\n- Se seu comportamento parece natural ou ensaiado.\n- Qual assunto observado provocou a reação mais intensa.\n- Uma provável área de ocupação ou hábito indicada por sinais visíveis.\n- Quem parece receber maior atenção ou respeito dela.\nSe a pessoa estiver tentando esconder ou falsificar deliberadamente esses sinais, o Mentalista realiza um teste de Intuição com vantagem contra a Enganação dela.\nLeitura Fria produz deduções baseadas no comportamento observado. Ela não revela pensamentos, memórias, segredos ou fatos que não tenham deixado sinais perceptíveis." }, { "name": "Sugestão Plausível", "text": "Depois de conversar com uma pessoa por pelo menos um minuto, o Mentalista poderá apresentar uma sugestão curta de maneira calculada.\nA sugestão deverá:\n- Ser possível de realizar.\n- Parecer razoável dentro da situação.\n- Não colocar a pessoa em perigo evidente.\n- Não contrariar diretamente seus vínculos, valores ou objetivos.\n- Exigir no máximo dez minutos para ser executada.\nExemplos:\n- “Talvez seja melhor verificar aquela porta.”\n- “Você deveria fazer uma pequena pausa.”\n- “Pode deixar esse objeto sobre a mesa.”\n- “Seria mais seguro esperar aqui.”\n- “Talvez aquela pessoa saiba responder melhor.”\n- “Você deveria conferir novamente os documentos.”\nO Mentalista realiza um teste de Persuasão ou Enganação contra a Vontade da pessoa.\nEm caso de sucesso, ela considera a sugestão razoável e poderá executá-la como se tivesse aceitado um conselho convincente.\nA pessoa não esquece quem apresentou a ideia e perceberá normalmente as consequências de suas ações.\nSugestão Plausível não poderá:\n- Forçar uma confissão.\n- Obrigar alguém a revelar um segredo.\n- Criar sentimentos.\n- Modificar memórias.\n- Fazer alguém abandonar um dever importante.\n- Provocar dano deliberado a si ou a outras pessoas.\n- Interferir nas decisões de um treinador durante uma batalha Pokémon.\nDepois de aceitar ou recusar uma sugestão, a mesma pessoa não poderá ser alvo de outra tentativa equivalente até que as circunstâncias mudem." }, { "name": "Desvio de Atenção", "text": "Quando alguém estiver prestes a perceber uma ação discreta, o Mentalista poderá usar sua reação para direcionar a atenção dessa pessoa a outro estímulo visível ou audível.\nO estímulo poderá ser:\n- Uma pergunta repentina.\n- Um gesto.\n- Um objeto derrubado.\n- Um movimento em outra direção.\n- Uma mudança no tom de voz.\n- Uma informação inesperada.\n- Uma falsa indicação de que algo aconteceu em outro local.\nO Mentalista realiza um teste de Enganação contra a Intuição do observador.\nEm caso de sucesso, o observador desvia momentaneamente sua atenção. Um aliado poderá refazer o teste de Furtividade ou Ladinagem que provocaria sua descoberta, mantendo o novo resultado.\nDesvio de Atenção poderá afetar somente um observador e uma tentativa. Ele não funciona contra alguém que já tenha percebido completamente a ação ou que não consiga perceber o estímulo criado." }],
	"mestre-pokemon": [{ "name": "Captura Calculada", "text": "Ao realizar um teste de Captura para acertar uma Poké Bola, o Mestre Pokémon poderá utilizar Sabedoria no lugar de Destreza.\nA escolha representa duas abordagens:\n```plain text\nDestreza: precisão e técnica de arremesso\nSabedoria: antecipação do movimento do Pokémon\n```\nAlém disso, recebe:\n```plain text\n+2 nos testes de Captura para acertar uma Poké Bola\n```\nEsse benefício se aplica somente ao teste que determina se a Poké Bola atinge o Pokémon.\nDepois do acerto, a porcentagem normal de captura é calculada sem outras alterações. A característica não modifica vida, condições, espécie, nível ou qualquer estatística do Pokémon." }, { "name": "Arremesso Controlado", "text": "Quando falha por até quatro pontos no teste para acertar uma Poké Bola:\n- A Poké Bola não é destruída.\n- Ela não é ativada.\n- Não atinge outro alvo acidentalmente.\n- É recuperada Imediatamente.\nA tentativa de captura ainda falha e a ação utilizada não é recuperada.\nFalhas por cinco ou mais poderão fazer a Poké Bola se perder, quebrar, cair em um local inacessível ou produzir outra consequência determinada pelo Mestre.\nSe a Poké Bola atingir o Pokémon e a captura falhar, ela será consumida normalmente. Arremesso Controlado protege apenas Poké Bolas que não chegaram a ser ativadas." }, { "name": "Experiência Multiespécie", "text": "O Mestre Pokémon está acostumado a conviver com espécies que possuem anatomias, comportamentos e necessidades muito diferentes.\nEle não sofre penalidades causadas exclusivamente pela falta de familiaridade com uma espécie ao realizar testes de:\n- Adestramento Pokémon.\n- Empatia Pokémon.\n- Medicina Pokémon.\n- Natureza.\nA característica não concede treinamento nessas perícias. Ela apenas remove penalidades de desconhecimento quando o Mestre já possui a perícia necessária para realizar a ação.\nExperiência Multiespécie não remove dificuldades causadas por comportamento hostil, anatomia extraordinária, falta de ferramentas ou condições perigosas." }, { "name": "Rotina de Equipe", "text": "Durante um período de descanso, o Mestre Pokémon poderá organizar os cuidados básicos de até seis Pokémon ao mesmo tempo.\nA rotina poderá incluir:\n- Distribuir alimentos e água.\n- Verificar sinais visíveis de desconforto.\n- Limpar e guardar equipamentos.\n- Preparar locais apropriados para descanso.\n- Conferir Poké Bolas.\n- Organizar itens pessoais dos Pokémon.\n- Verificar se algum integrante precisa de atendimento especializado.\n- Adaptar o acampamento para espécies diferentes.\nO tempo necessário será o mesmo que outra pessoa normalmente utilizaria para cuidar de um único Pokémon.\nRotina de Equipe não cura ferimentos, remove condições ou substitui Medicina Pokémon. Ela também não concede Amizade adicional, experiência ou qualquer benefício de combate." }],
	"psiquico": [{ "name": "Manifestação Psíquica", "text": "Sabedoria será o atributo principal das capacidades psíquicas da classe.\nQuando um poder exigir uma CD, ela será calculada da seguinte forma:\n```plain text\nCD psíquica = 8 + bônus de proficiência + modificador de Sabedoria\n```\nO Psíquico precisa estar consciente e ser capaz de se concentrar para utilizar suas capacidades.\nEle poderá sustentar somente um efeito psíquico que exija concentração por vez. Iniciar outro encerra o anterior.\nCondições que impeçam concentração também impedem a utilização desses poderes." }, { "name": "Telepatia", "text": "O Psíquico poderá estabelecer comunicação mental com uma criatura consciente e disposta que consiga perceber dentro de um alcance de:\n```plain text\n18 metros\n```\nSe ambos compartilharem um idioma, poderão trocar palavras e frases mentalmente.\nSem um idioma compartilhado, poderão transmitir apenas:\n- Emoções.\n- Imagens simples.\n- Sensações.\n- Intenções imediatas.\n- Conceitos básicos como perigo, ajuda, espera ou aproximação.\nA comunicação permanece enquanto ambos estiverem dentro do alcance e o Psíquico mantiver a concentração.\nTelepatia não permite:\n- Ler pensamentos sem permissão.\n- Acessar memórias.\n- Descobrir mentiras.\n- Obrigar alguém a responder.\n- Comunicar-se com uma criatura inconsciente.\n- Controlar ações.\nCom Pokémon dispostos, a comunicação transmite emoções e conceitos simples. Pokémon capazes de compreender linguagem complexa ou que possuam capacidades telepáticas próprias poderão se comunicar de maneira mais elaborada.\nDurante batalhas Pokémon, a Telepatia não concede ações adicionais, prioridade, informações ocultas ou qualquer benefício mecânico. Uma mensagem telepática conta como comunicação normal do treinador." }, { "name": "Telecinese Menor", "text": "O Psíquico poderá mover mentalmente um objeto solto de até:\n```plain text\n5 quilogramas\n```\nO objeto deverá estar a até 9 metros e permanecer dentro desse alcance durante o movimento.\nA Telecinese Menor poderá:\n- Erguer ou abaixar um objeto.\n- Aproximá-lo ou afastá-lo.\n- Abrir uma porta ou gaveta destrancada.\n- Acionar um botão ou alavanca simples.\n- Derramar o conteúdo de um recipiente.\n- Recuperar um objeto em local difícil de alcançar.\n- Manter algo leve suspenso.\nO objeto se desloca até 9 metros por rodada ou período equivalente enquanto o Psíquico mantiver a concentração.\nA característica não poderá:\n- Mover criaturas.\n- Retirar um objeto firmemente segurado.\n- Romper fechaduras.\n- Executar trabalhos que exijam grande precisão.\n- Realizar ataques.\n- Ativar uma Poké Bola.\n- Arremessar uma Poké Bola para realizar uma captura.\n- Manipular o corpo de alguém.\n- Interferir em uma batalha Pokémon.\nTalentos exclusivos poderão futuramente aumentar o peso, alcance e precisão da Telecinese." }, { "name": "Percepção Extrassensorial", "text": "Ao se concentrar, o Psíquico poderá perceber a presença de mentes conscientes em um raio de:\n```plain text\n6 metros\n```\nEle identifica:\n- A quantidade aproximada de presenças conscientes.\n- A direção aproximada de cada presença.\n- Se uma presença está se aproximando ou se afastando.\n- Se uma presença demonstra uma emoção extremamente intensa.\nA percepção atravessa obstáculos comuns, como portas e paredes finas, mas será bloqueada por barreiras especialmente densas, isolamento psíquico ou materiais preparados para impedir esse tipo de capacidade.\nPercepção Extrassensorial não revela:\n- Identidade.\n- Espécie.\n- Aparência.\n- Pensamentos.\n- Memórias.\n- Intenções específicas.\n- Localização exata.\n- Diferença entre uma pessoa e um Pokémon.\nCriaturas inconscientes não são detectadas. Uma criatura que saiba ocultar sua presença psíquica poderá realizar uma resistência de Vontade contra a CD psíquica do personagem.\nEnquanto utiliza essa percepção, o Psíquico precisa manter a concentração e não poderá sustentar outra capacidade psíquica que também a exija." }],
	"tecnologo": [{ "name": "Operador Universal", "text": "O Tecnólogo não sofre penalidades causadas exclusivamente por falta de familiaridade ao utilizar um computador, máquina ou dispositivo eletrônico que possua uma interface acessível.\nDepois de examinar o equipamento por pelo menos um minuto, identifica:\n- Sua função principal.\n- Seus controles básicos.\n- Seu estado de funcionamento.\n- Como ligá-lo ou desligá-lo de maneira segura.\n- Se apresenta uma falha visível.\n- Se precisa de uma fonte externa de energia.\n- Quais acessórios ou conexões parecem compatíveis.\nA característica permite operar funções comuns, mas não concede senhas, autorizações ou conhecimento sobre recursos ocultos.\nEquipamentos experimentais, alienígenas, severamente danificados ou construídos com uma tecnologia completamente desconhecida ainda poderão exigir testes e estudo adicional." }, { "name": "Manutenção Segura", "text": "Quando utiliza Tecnologia para programar, reparar ou modificar um dispositivo e falha por até quatro pontos:\n- O equipamento não sofre dano adicional.\n- Dados não são apagados.\n- Componentes não são queimados.\n- O sistema não é bloqueado permanentemente.\n- A falha não ativa automaticamente mecanismos perigosos.\n- A ação pretendida não é concluída.\nUma nova tentativa exige mais tempo, ferramentas diferentes, peças adicionais ou mudança na abordagem.\nFalhas por cinco ou mais produzem as consequências normais.\nManutenção Segura não protege contra sistemas que estejam preparados especificamente para reagir a tentativas de acesso ou adulteração." }, { "name": "Protótipo Tecnológico", "text": "Com ferramentas, componentes compatíveis e uma hora de trabalho, o Tecnólogo poderá transformar um objeto comum em um Protótipo Tecnológico com uma função especial.\nA função precisa possuir uma explicação tecnológica possível dentro do mundo Pokémon. Ela poderá utilizar componentes como:\n- Sensores.\n- Circuitos.\n- Pequenos motores.\n- Câmeras.\n- Emissores de luz ou som.\n- Baterias.\n- Programas.\n- Transmissores.\n- Sistemas de controle.\n- Materiais especiais.\nExemplos de protótipos iniciais:\n- Uma lanterna que ajusta automaticamente sua intensidade.\n- Um recipiente que conserva sua temperatura.\n- Um dispositivo que emite um alerta ao detectar movimento.\n- Um gravador que começa a funcionar ao reconhecer determinado som.\n- Uma bússola que aponta para um pequeno transmissor preparado.\n- Óculos que ampliam objetos distantes.\n- Uma pulseira que vibra ao receber um sinal.\n- Um marcador que registra o caminho percorrido.\n- Uma caixa que somente abre após reconhecer um código.\n- Um aparelho que mede alterações simples no ambiente.\nQualquer pessoa que conheça a forma de ativação poderá utilizar o protótipo. Ela não precisa ser treinada em Tecnologia.\nO Tecnólogo poderá manter somente:\n```plain text\n1 Protótipo Tecnológico funcionando\n```\nQuando criar um novo protótipo, a programação especial do anterior apresenta um erro e deixa de funcionar. O objeto anterior perde sua função tecnológica especial e volta a ser um item comum, sem ser destruído.\nO protótipo também deixa de funcionar se:\n- For danificado.\n- Ficar sem energia.\n- Perder um componente essencial.\n- Sair das condições para as quais foi projetado.\nProtótipo Tecnológico não poderá:\n- Criar energia ilimitada.\n- Produzir um efeito sem componentes capazes de explicá-lo.\n- Transformar uma arma comum em uma arma extraordinária.\n- Aumentar dano, precisão ou outros valores de combate.\n- Alterar atributos ou golpes de Pokémon.\n- Reproduzir capacidades exclusivas de Pokémon sem tecnologia apropriada.\n- Ignorar automaticamente senhas ou sistemas de segurança.\n- Tomar decisões complexas como uma inteligência artificial.\n<page url=\"https://app.notion.com/p/3e2508f8aa6c80e98323d0436a30603a\">Protótipos Tecnológicos Iniciais</page>" }],
};
